mapper.update:
update SIMULATION
set SIMULATION_START_DATE = #{simulationStartDate},
    SIMULATION_DUE_DATE = #{simulationDueDate},
    SIMULATION_END_AMOUNT = #{simulationEndAmount}
where SIMULATION_ID = #{simulationId}
  and CONFIRMED_AT is null

update SIMULATION
set SIMULATION_END_AMOUNT = #{simulationEndAmount},
    EXPECT_PREP_MONTHS = #{expectPrepMonths}
where SIMULATION_ID = #{simulationId}
  and CONFIRMED_AT is null

mapper.delete:
delete from SIMULATION
where SIMULATION_ID = #{simulationId}
    and CONFIRMED_AT is not null
